    bands=[k*step for k in range(nb)]; slots=[k*step for k in range(nc_)]
    mr=mc=None
    for r in range(n):
        for c in range(m):
            if g[r][c]==2: mr,mc=r,c; break
        if mr is not None: break
    orr=mr-mr%step; occ0=mc-mc%step
    P={(r-orr,c-occ0) for r in range(orr,min(orr+s,n)) for c in range(occ0,min(occ0+s,m)) if g[r][c]==2}
    occ={}
    for bi,rs in enumerate(bands):
        for ci,cs in enumerate(slots):
            if rs+s>n or cs+s>m: continue
            if any(g[rs+r][cs+c]==2 for r in range(s) for c in range(s)):
                occ[(bi,ci)]=(rs,cs)
    out=[[0]*m for _ in range(n)]
    def draw(bi,ci,rs,cs):
        for r,c in P: out[rs+r][cs+c]=2
        if (bi,ci) in P: out[rs+bi][cs+ci]=8
    for (bi,ci),(rs,cs) in occ.items(): draw(bi,ci,rs,cs)
    for bi,rs in enumerate(bands):
        for ci,cs in enumerate(slots):
            if (bi,ci) in occ or rs+s>n or cs+s>m: continue
            if all(g[rs+r][cs+c]==3 for r in range(s) for c in range(s)) and (bi,ci) in P:
                draw(bi,ci,rs,cs)
    return out

for k,(ii,oo) in enumerate(pairs):
    t=transform(ii)
    print(k, t==oo, [(r,c,oo[r][c],t[r][c]) for r in range(len(oo)) for c in range(len(oo[0])) if oo[r][c]!=t[r][c]][:8])
